import type {SidebarsConfig} from '@docusaurus/plugin-content-docs';

/**
 * Core Internals handbook sidebar.
 *
 * Consumed by the docs plugin instance (id: 'core-internals') which reads
 * directly from the `core-internals/docs/core-internals` submodule. The
 * handbook ships a `_category_.json` in every part directory and a
 * `sidebar_position` in every chapter's front matter, so the whole tree is
 * autogenerated -- chapters added upstream appear here without a change on
 * the site side.
 */
const sidebarsCoreInternals: SidebarsConfig = {
  coreInternalsSidebar: [
    {type: 'autogenerated', dirName: '.'},
  ],
};

export default sidebarsCoreInternals;
